import sqlite3

def validate_entry_data(data):
    required_fields = ['title', 'content', 'createdBy']
    for field in required_fields:
        if field not in data:
            return False
    return True

# Example usage
entry_data = {'title': 'Sample Title', 'content': 'Sample Content', 'createdBy': 'User1'}
print(validate_entry_data(entry_data))  # Should print: True

invalid_entry_data = {'title': 'Sample Title', 'content': 'Sample Content'}
print(validate_entry_data(invalid_entry_data))  # Should print: False
